(()=>{const t=document.querySelector(".resume-biography"),e=t?.querySelector(".home-language-switch");if(!e)return;const i=t.querySelectorAll("[data-home-language]"),n=e.querySelectorAll("[data-set-home-language]"),s=e=>{i.forEach(t=>{t.hidden=t.dataset.homeLanguage!==e}),n.forEach(t=>{t.setAttribute("aria-pressed",String(t.dataset.setHomeLanguage===e))})};let o="en";try{localStorage.getItem("home-language")==="zh"&&(o="zh")}catch{}s(o),e.hidden=!1,n.forEach(e=>e.addEventListener("click",()=>{const t=e.dataset.setHomeLanguage;s(t);try{localStorage.setItem("home-language",t)}catch{}}))})()